jQuery(function() {
    $('#preloader').fadeOut(200);
    $('#main-wrapper').addClass('show');

    $('body').attr('data-sidebar-style') === "mini" ? $(".hamburger").addClass('is-active') : $(".hamburger").removeClass('is-active')
});

(function($) {
    "use strict";
    $("#menu").metisMenu();

    $('.nk-nav-scroll').slimscroll({
        position: "right",
        size: "5px",
        height: "100%",
        color: "transparent"
    });

    $(".nav-control").on('click', function() {

        $('#main-wrapper').toggleClass("menu-toggle");

        $(".hamburger").toggleClass("is-active");
    });

    $(function() {
        for (var nk = window.location, 
            o = $("ul#menu a").filter(function() {
                    return this.href == nk;
                })
                .addClass("active")
                .parent()
                .addClass("active");;) {
            if (!o.is("li")) break;
            o = o.parent()
                .addClass("in")
                .parent()
                .addClass("active");
        }
    });

    // content-body 最小高度 = 视口高度 - header/footer 占位，保证内容为空时 footer 无需滚动即可见
    function setContentMinHeight() {
        var vh = window.innerHeight || document.documentElement.clientHeight;
        var headerH = $('body').attr('data-header-position') === "fixed" ? 0 : ($('.header').outerHeight() || 0);
        var footerH = $('.footer').outerHeight() || 0;
        // content-body 首个子元素的 margin-top（如 .mt-3 的 16px）会塌陷到父级之外，需一并预留
        var $first = $(".content-body").children().first();
        var collapse = $first.length ? (parseFloat($first.css("marginTop")) || 0) : 0;
        $(".content-body").css("min-height", Math.max(vh - headerH - footerH - collapse, 0) + "px");
    }
    $(function() {
        setContentMinHeight();
    });
    $(window).on("resize", setContentMinHeight);

    $('.selectpicker').selectpicker();
    $('[data-toggle="popover"]').popover();
    $('[data-toggle="tooltip"]').tooltip();

    const headerHight = $('.header').innerHeight();

    $(window).scroll(function() {
        if($('body').attr('data-layout') === "horizontal" && $('body').attr('data-header-position') === "static" && $('body').attr('data-sidebar-position') === "fixed")
            $(this.window).scrollTop() >= headerHight ? $('.metismenu').addClass('fixed') :  $('.metismenu').removeClass('fixed')
    });

    $('.sidebar-right-trigger').on('click', function() {
        $('.sidebar-right').toggleClass('show');
    });

})(jQuery);
